// All four collections arrive as items from Fetch Categories (last in chain)
// We reach back to each node by name

const interests = $('Webhook').first().json.query.interests || [];
const courseList = $('Fetch Courses').first().json || [];
const reviews = $('Fetch Reviews').first().json || [];
const skills = $('Fetch Skills').first().json || [];
const categories = $('Fetch Categories').first().json || [];

return [{
  interests,
  courseList,
  reviews,
  skills,
  categories,
  formationIds: courseList.map(c => c._id || c.id)
}];

const input = $input.first().json;
const validIds = $('Merge and Format').first().json.formationIds || [];

let rec;
try {
  if (typeof input.output === 'object' && input.output !== null) {
    rec = input.output;
  } else if (typeof input.output === 'string') {
    rec = JSON.parse(input.output);
  } else {
    throw new Error('Invalid output format');
  }
} catch (e) {
  return [{ error: 'Failed to parse AI response', details: e.message }];
}

if (!rec.recommendedCourseId || !validIds.includes(rec.recommendedCourseId)) {
  return [{ error: 'Invalid course ID: ' + rec.recommendedCourseId }];
}

return [rec];
